// A small toast store in the style of react-hot-toast, backed by Base UI's
// toast manager so `toast()` works from anywhere.
import * as React from "react"
import { Toast as ToastPrimitive } from "@base-ui/react/toast"

import type { ToastActionElement, ToastProps } from "./toast"

const TOAST_LIMIT = 1

type ToasterToast = Omit<ToastProps, "toast"> & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
  duration?: number
}

type Toast = Omit<ToasterToast, "id">

// Fields the Base UI toast object has no slot for. They ride on
// `toast.data`, and the Toaster puts them back when it renders.
type ToastData = {
  action?: ToastActionElement
  rootProps: Omit<Toast, "title" | "description" | "action" | "duration">
}

// One manager for the whole module, so `toast()` works outside React. The
// Toaster hands it to <ToastProvider toastManager={...}>.
const toastManager = ToastPrimitive.createToastManager()

interface State {
  toasts: ToasterToast[]
}

let memoryState: State = { toasts: [] }

const listeners: Array<(state: State) => void> = []

function setMemoryState(toasts: ToasterToast[]) {
  memoryState = { toasts }
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

function toManagerOptions({
  title,
  description,
  action,
  duration,
  ...rootProps
}: Toast) {
  return {
    title,
    description,
    timeout: duration,
    data: { action, rootProps } satisfies ToastData,
  }
}

/**
 * Changes that start inside the provider (timeout, swipe, the close button)
 * never pass through the manager, so the mounted Toaster copies the
 * provider's list back here whenever it changes. Without this,
 * useToast().toasts would keep toasts that have already left the screen.
 */
function syncFromManager(
  toasts: Array<{
    id: string
    title?: React.ReactNode
    description?: React.ReactNode
    data?: unknown
  }>
) {
  // Copy every time: the provider only emits a new array when something
  // changed, and comparing ids alone would miss an edited title. Listeners
  // never write back to the manager, so this cannot loop.
  setMemoryState(
    toasts.map(({ id, title, description, data }) => {
      // SAFETY: `data` is what this module stored on the toast, so it has
      // the ToastData shape written on the way in.
      const { action, rootProps } = (data ?? {}) as Partial<ToastData>
      // SAFETY: the object restates ToasterToast's own fields from the toast
      // being copied, plus the root props stored with it.
      return { id, title, description, action, ...rootProps } as ToasterToast
    })
  )
}

function dismissToast(toastId?: string) {
  // close() with no id closes every toast.
  toastManager.close(toastId)
  setMemoryState(
    toastId === undefined
      ? []
      : memoryState.toasts.filter((t) => t.id !== toastId)
  )
}

function toast({ ...props }: Toast) {
  const id = toastManager.add(toManagerOptions(props))

  setMemoryState(
    [{ ...props, id }, ...memoryState.toasts].slice(0, TOAST_LIMIT)
  )

  const update = (props: ToasterToast) => {
    const current = memoryState.toasts.find((t) => t.id === id)
    const { id: _id, ...merged } = { ...current, ...props }
    toastManager.update(id, toManagerOptions(merged))
    setMemoryState(
      memoryState.toasts.map((t) => (t.id === id ? { ...t, ...props, id } : t))
    )
  }

  const dismiss = () => dismissToast(id)

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dismissToast(toastId),
  }
}

export {
  useToast,
  toast,
  toastManager,
  syncFromManager,
  TOAST_LIMIT,
  type ToastData,
}
